const { fonte, janela } = $json;
const versaoApi = 'v26';
const administradora = String(fonte.managerExternalId || fonte.externalId).replace(/\D/g, '');
const cliente = String(fonte.externalId).replace(/\D/g, '');
const DIA_MS = 86_400_000;
const incluirEntidades = fonte.comDimensoes !== false && janela.end >= new Date(Date.now() - 2 * DIA_MS).toISOString().slice(0, 10);

const periodo = `segments.date BETWEEN '${janela.start}' AND '${janela.end}'`;
const comImpressao = `${periodo} AND metrics.impressions > 0`;
const BASICAS = 'metrics.cost_micros, metrics.impressions, metrics.clicks, metrics.conversions, metrics.conversions_value, metrics.all_conversions, metrics.all_conversions_value, metrics.interactions';
const COMPLETAS = `${BASICAS}, metrics.video_trueview_views`;
const PARCELAS = 'metrics.search_impression_share, metrics.search_budget_lost_impression_share, metrics.search_rank_lost_impression_share, metrics.search_top_impression_share, metrics.search_absolute_top_impression_share';

const fatos = [
  { tabela: 'fato_google_campanha_diario', obrigatoria: true, gaql: `SELECT campaign.id, campaign.name, segments.date, ${COMPLETAS}, ${PARCELAS} FROM campaign WHERE ${periodo}` },
  { tabela: 'fato_google_anuncio_diario', gaql: `SELECT campaign.id, ad_group.id, ad_group_ad.ad.id, segments.date, ${COMPLETAS} FROM ad_group_ad WHERE ${comImpressao}` },
  { tabela: 'fato_google_palavra_chave_diario', gaql: `SELECT campaign.id, ad_group.id, ad_group_criterion.criterion_id, segments.date, ${COMPLETAS} FROM keyword_view WHERE ${comImpressao}` },
  { tabela: 'fato_google_termo_pesquisa_diario', gaql: `SELECT campaign.id, ad_group.id, search_term_view.search_term, search_term_view.status, segments.date, ${COMPLETAS} FROM search_term_view WHERE ${comImpressao}` },
  { tabela: 'fato_google_conversao_diario', gaql: `SELECT campaign.id, segments.conversion_action, segments.conversion_action_name, segments.conversion_action_category, segments.date, metrics.conversions, metrics.conversions_value, metrics.all_conversions, metrics.all_conversions_value FROM campaign WHERE ${periodo} AND metrics.all_conversions > 0` },
  { tabela: 'fato_google_dispositivo_diario', gaql: `SELECT campaign.id, segments.device, segments.date, ${COMPLETAS} FROM campaign WHERE ${comImpressao}` },
  { tabela: 'fato_google_rede_diario', gaql: `SELECT campaign.id, segments.ad_network_type, segments.date, ${COMPLETAS} FROM campaign WHERE ${comImpressao}` },
  { tabela: 'fato_google_geo_diario', gaql: `SELECT campaign.id, geographic_view.country_criterion_id, geographic_view.location_type, segments.date, ${COMPLETAS} FROM geographic_view WHERE ${comImpressao}` },
  { tabela: 'fato_google_idade_diario', gaql: `SELECT campaign.id, ad_group.id, ad_group_criterion.age_range.type, segments.date, ${COMPLETAS} FROM age_range_view WHERE ${comImpressao}` },
  { tabela: 'fato_google_genero_diario', gaql: `SELECT campaign.id, ad_group.id, ad_group_criterion.gender.type, segments.date, ${COMPLETAS} FROM gender_view WHERE ${comImpressao}` },
  { tabela: 'fato_google_grupo_ativos_diario', gaql: `SELECT campaign.id, asset_group.id, segments.date, ${BASICAS} FROM asset_group WHERE ${comImpressao}` },
];

const entidades = [
  { tabela: 'dim_google_campanha_scd2', gaql: 'SELECT campaign.id, campaign.name, campaign.status, campaign.advertising_channel_type, campaign.advertising_channel_sub_type, campaign.bidding_strategy_type, campaign_budget.amount_micros, campaign_budget.explicitly_shared FROM campaign' },
  { tabela: 'dim_google_grupo_anuncios_scd2', gaql: 'SELECT ad_group.id, campaign.id, ad_group.name, ad_group.status, ad_group.type FROM ad_group' },
  { tabela: 'dim_google_anuncio_scd2', gaql: 'SELECT ad_group_ad.ad.id, ad_group.id, campaign.id, ad_group_ad.ad.name, ad_group_ad.ad.type, ad_group_ad.status, ad_group_ad.policy_summary.approval_status FROM ad_group_ad' },
  { tabela: 'dim_google_palavra_chave_scd2', gaql: "SELECT ad_group_criterion.criterion_id, ad_group.id, campaign.id, ad_group_criterion.keyword.text, ad_group_criterion.keyword.match_type, ad_group_criterion.status, ad_group_criterion.negative, ad_group_criterion.quality_info.quality_score FROM ad_group_criterion WHERE ad_group_criterion.type = 'KEYWORD'" },
  { tabela: 'dim_google_grupo_ativos_scd2', gaql: 'SELECT asset_group.id, campaign.id, asset_group.name, asset_group.status FROM asset_group' },
];

const consultas = [...fatos, ...(incluirEntidades ? entidades : [])];
const url = `https://googleads.googleapis.com/${versaoApi}/customers/${cliente}/googleAds:searchStream`;
const inicio = Date.now();

return consultas.map((consulta) => ({
  json: { inicio, versaoApi, fonte, url, administradora, tabela: consulta.tabela, obrigatoria: consulta.obrigatoria === true, corpo: { query: consulta.gaql } },
}));

const pedidos = $('Montar requisição').all().map((item) => item.json);
const contexto = pedidos[0];
const respostas = $input.all().map((item) => item.json);
const requests = respostas.length;
const bytes = respostas.reduce((total, resposta) => total + JSON.stringify(resposta.body ?? {}).length, 0);

function devolver(linhas, falhas) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - contexto.inicio },
      falhas,
      requests,
      versaoApi: contexto.versaoApi,
    },
  }];
}

const CONFIGURACAO_DO_PROJETO = /SERVICE_DISABLED|accessNotConfigured|has not been used in project/;
const SINAIS_DE_LIMITE = /RESOURCE_EXHAUSTED|RATE_LIMIT|rateLimitExceeded|userRateLimitExceeded|quotaExceeded|dailyLimitExceeded|Quota exceeded|Exhausted|Too many requests/i;
const SINAIS_DE_COTA_DIARIA = /dailyLimitExceeded|quotaExceeded|per day|PerDay|daily|Number of operations/i;
const ESCOPO_INSUFICIENTE = /ACCESS_TOKEN_SCOPE_INSUFFICIENT|insufficient authentication scopes/i;
const PERMISSAO_NEGADA = /PERMISSION_DENIED|caller does not have permission|does not have (sufficient )?permission|insufficientPermissions/i;
function semPermissaoNoRecurso(statusCode, texto) {
  return statusCode === 403 && PERMISSAO_NEGADA.test(texto) && !ESCOPO_INSUFICIENTE.test(texto) && !/DEVELOPER_TOKEN/.test(texto);
}
function mensagemSemAcesso() {
  const alvo = typeof contexto === 'undefined' ? '' : String(contexto?.fonte?.externalId ?? '').split('locations/').pop();
  return `Sem permissão na conta ${alvo} — a conta autorizada não acessa esta conta`.replace('  ', ' ').slice(0, 500);
}
function falhaDaRecusa(statusCode, erro, detalhe) {
  const texto = JSON.stringify(erro ?? {});
  if (CONFIGURACAO_DO_PROJETO.test(texto)) return { causa: 'api_recusou', detalhe };
  if (statusCode === 429 || SINAIS_DE_LIMITE.test(texto)) {
    return { causa: 'limite_de_uso', detalhe: String(detalhe).slice(0, 500), pausa: SINAIS_DE_COTA_DIARIA.test(texto) ? 'cota_diaria' : 'limite_temporario', minutos: null };
  }
  if (/DEVELOPER_TOKEN/.test(texto)) return { causa: 'api_recusou', detalhe };
  if (semPermissaoNoRecurso(statusCode, texto)) return { causa: 'sem_acesso', detalhe: mensagemSemAcesso() };
  if (statusCode === 401 || statusCode === 403) return { causa: 'reauth_pending', detalhe };
  return { causa: 'api_recusou', detalhe };
}

const respostaOk = (resposta) => !resposta?.error && resposta?.statusCode >= 200 && resposta?.statusCode < 300;
const falhaDaResposta = (resposta, pedido) => {
  if (resposta?.error) return { causa: 'api_recusou', detalhe: `falha de rede (${pedido?.tabela}): ${resposta.error?.message ?? String(resposta.error)}`.slice(0, 500) };
  const erro = Array.isArray(resposta?.body) ? resposta.body[0]?.error : resposta?.body?.error;
  const motivos = (erro?.details ?? []).flatMap((detalhe) => detalhe?.errors ?? []).map((falha) => falha?.message).filter(Boolean);
  const detalhe = `${pedido?.tabela}: ${motivos.length > 0 ? motivos.join(' | ') : String(erro?.message || `HTTP ${resposta?.statusCode}`)}`.slice(0, 500);
  return falhaDaRecusa(resposta?.statusCode, erro, detalhe);
};

const recusas = respostas
  .map((resposta, indice) => ({ resposta, pedido: pedidos[indice] }))
  .filter(({ resposta }) => !respostaOk(resposta))
  .map(({ resposta, pedido }) => ({ pedido, falha: falhaDaResposta(resposta, pedido) }));
const recusaFatal = recusas.find(({ falha }) => falha.causa === 'limite_de_uso')
  ?? recusas.find(({ pedido }) => pedido?.obrigatoria)
  ?? recusas.find(({ falha }) => falha.causa === 'reauth_pending' || falha.causa === 'sem_acesso');
const incompletas = recusas
  .filter((recusa) => recusa !== recusaFatal)
  .map(({ falha }) => ({ causa: 'coleta_incompleta', detalhe: falha.detalhe }));

const moeda = contexto.fonte.currency || 'BRL';
const numero = (valor) => (valor === undefined || valor === null || valor === '' ? null : Number(valor));
const inteiro = (valor) => (valor === undefined || valor === null || valor === '' ? 0 : Number(valor));
const dinheiro = (micros) => (micros === undefined || micros === null ? null : Number(micros) / 1_000_000);
const parcela = (valor) => {
  const n = numero(valor);
  return n === null || Number.isNaN(n) ? null : Math.round(n * 1_000_000) / 1_000_000;
};
const texto = (valor) => (valor === undefined || valor === null ? null : String(valor));
const idDoRecurso = (recurso) => (recurso ? String(recurso).split('/').pop() : '');

const completas = (r) => ({
  investimento: dinheiro(r.metrics?.costMicros) ?? 0,
  impressoes: inteiro(r.metrics?.impressions),
  cliques: inteiro(r.metrics?.clicks),
  conversoes: numero(r.metrics?.conversions) ?? 0,
  receita: numero(r.metrics?.conversionsValue) ?? 0,
  todas_conversoes: numero(r.metrics?.allConversions) ?? 0,
  todas_conversoes_receita: numero(r.metrics?.allConversionsValue) ?? 0,
  interacoes: inteiro(r.metrics?.interactions),
  visualizacoes_video: inteiro(r.metrics?.videoTrueviewViews),
  moeda,
});
const basicas = (r) => {
  const { visualizacoes_video: _descartada, ...resto } = completas(r);
  return resto;
};
const base = (r) => ({ data_dia: r.segments?.date ?? null, external_campaign_id: String(r.campaign?.id ?? '') });
const textoOuVazio = (valor) => texto(valor) ?? '';

const MAPAS = {
  fato_google_campanha_diario: (r) => ({
    ...base(r),
    ...completas(r),
    parcela_impressoes_pesquisa: parcela(r.metrics?.searchImpressionShare),
    perdida_orcamento: parcela(r.metrics?.searchBudgetLostImpressionShare),
    perdida_ranking: parcela(r.metrics?.searchRankLostImpressionShare),
    parcela_topo: parcela(r.metrics?.searchTopImpressionShare),
    parcela_topo_absoluto: parcela(r.metrics?.searchAbsoluteTopImpressionShare),
  }),
  fato_google_anuncio_diario: (r) => ({ ...base(r), ad_group_id: String(r.adGroup?.id ?? ''), ad_id: String(r.adGroupAd?.ad?.id ?? ''), ...completas(r) }),
  fato_google_palavra_chave_diario: (r) => ({ ...base(r), ad_group_id: String(r.adGroup?.id ?? ''), criterion_id: String(r.adGroupCriterion?.criterionId ?? ''), ...completas(r) }),
  fato_google_termo_pesquisa_diario: (r) => ({
    ...base(r),
    ad_group_id: String(r.adGroup?.id ?? ''),
    termo: textoOuVazio(r.searchTermView?.searchTerm).slice(0, 500),
    status_termo: texto(r.searchTermView?.status),
    ...completas(r),
  }),
  fato_google_conversao_diario: (r) => ({
    ...base(r),
    conversion_action_id: idDoRecurso(r.segments?.conversionAction),
    acao_nome: texto(r.segments?.conversionActionName),
    acao_categoria: texto(r.segments?.conversionActionCategory),
    conversoes: numero(r.metrics?.conversions) ?? 0,
    receita: numero(r.metrics?.conversionsValue) ?? 0,
    todas_conversoes: numero(r.metrics?.allConversions) ?? 0,
    todas_conversoes_receita: numero(r.metrics?.allConversionsValue) ?? 0,
    moeda,
  }),
  fato_google_dispositivo_diario: (r) => ({ ...base(r), dispositivo: textoOuVazio(r.segments?.device), ...completas(r) }),
  fato_google_rede_diario: (r) => ({ ...base(r), rede: textoOuVazio(r.segments?.adNetworkType), ...completas(r) }),
  fato_google_geo_diario: (r) => ({
    ...base(r),
    pais_criterio_id: String(r.geographicView?.countryCriterionId ?? ''),
    tipo_localizacao: textoOuVazio(r.geographicView?.locationType),
    ...completas(r),
  }),
  fato_google_idade_diario: (r) => ({ ...base(r), ad_group_id: String(r.adGroup?.id ?? ''), faixa_etaria: textoOuVazio(r.adGroupCriterion?.ageRange?.type), ...completas(r) }),
  fato_google_genero_diario: (r) => ({ ...base(r), ad_group_id: String(r.adGroup?.id ?? ''), genero: textoOuVazio(r.adGroupCriterion?.gender?.type), ...completas(r) }),
  fato_google_grupo_ativos_diario: (r) => ({ ...base(r), asset_group_id: String(r.assetGroup?.id ?? ''), ...basicas(r) }),
  dim_google_campanha_scd2: (r) => ({
    external_campaign_id: String(r.campaign?.id ?? ''),
    nome: texto(r.campaign?.name),
    status: texto(r.campaign?.status),
    canal: texto(r.campaign?.advertisingChannelType),
    subcanal: texto(r.campaign?.advertisingChannelSubType),
    estrategia_lance: texto(r.campaign?.biddingStrategyType),
    orcamento: dinheiro(r.campaignBudget?.amountMicros),
    orcamento_compartilhado: r.campaignBudget?.explicitlyShared ?? null,
  }),
  dim_google_grupo_anuncios_scd2: (r) => ({
    ad_group_id: String(r.adGroup?.id ?? ''),
    external_campaign_id: String(r.campaign?.id ?? ''),
    nome: texto(r.adGroup?.name),
    status: texto(r.adGroup?.status),
    tipo: texto(r.adGroup?.type),
  }),
  dim_google_anuncio_scd2: (r) => ({
    ad_id: String(r.adGroupAd?.ad?.id ?? ''),
    ad_group_id: String(r.adGroup?.id ?? ''),
    external_campaign_id: String(r.campaign?.id ?? ''),
    nome: texto(r.adGroupAd?.ad?.name),
    tipo: texto(r.adGroupAd?.ad?.type),
    status: texto(r.adGroupAd?.status),
    aprovacao: texto(r.adGroupAd?.policySummary?.approvalStatus),
  }),
  dim_google_palavra_chave_scd2: (r) => ({
    ad_group_id: String(r.adGroup?.id ?? ''),
    criterion_id: String(r.adGroupCriterion?.criterionId ?? ''),
    external_campaign_id: String(r.campaign?.id ?? ''),
    texto: texto(r.adGroupCriterion?.keyword?.text),
    correspondencia: texto(r.adGroupCriterion?.keyword?.matchType),
    status: texto(r.adGroupCriterion?.status),
    negativa: r.adGroupCriterion?.negative ?? null,
    nota_qualidade: numero(r.adGroupCriterion?.qualityInfo?.qualityScore),
  }),
  dim_google_grupo_ativos_scd2: (r) => ({
    asset_group_id: String(r.assetGroup?.id ?? ''),
    external_campaign_id: String(r.campaign?.id ?? ''),
    nome: texto(r.assetGroup?.name),
    status: texto(r.assetGroup?.status),
  }),
};

const linhas = [];
let linhasDeFato = 0;
respostas.forEach((resposta, indice) => {
  if (!respostaOk(resposta)) return;
  const tabela = pedidos[indice].tabela;
  const lotes = Array.isArray(resposta.body) ? resposta.body : [resposta.body];
  for (const resultado of lotes.flatMap((lote) => lote?.results ?? [])) {
    const linha = MAPAS[tabela](resultado);
    linhas.push({ ...linha, _tabela: tabela });
    if (tabela.startsWith('fato_')) linhasDeFato += 1;
    if (tabela === 'fato_google_campanha_diario') {
      linhas.push({
        externalCampaignId: linha.external_campaign_id,
        campaignName: resultado.campaign?.name ?? null,
        metricDate: linha.data_dia,
        spend: linha.investimento,
        impressions: linha.impressoes,
        clicks: linha.cliques,
        conversions: linha.conversoes,
        revenue: linha.receita,
        currency: moeda,
        versaoApi: contexto.versaoApi,
      });
    }
  }
});

if (recusaFatal) return devolver(linhas, [recusaFatal.falha, ...incompletas]);
if (linhasDeFato === 0) return devolver([], incompletas.length > 0 ? incompletas : [{ causa: 'sem_dados_no_periodo', detalhe: null }]);
return devolver(linhas, incompletas);
